    { const char * tb_v396 = "#define stderr ((FILE *)2)\n"; *(const char * *)tb_grow(v_lines) = tb_v396; }
    { const char * tb_v397 = "typedef long pthread_t;   // 8 байт, как адрес: раскладка задачи та же, что в обычной программе\n"; *(const char * *)tb_grow(v_lines) = tb_v397; }
    { const char * tb_v398 = "typedef int pthread_mutex_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v398; }
    { const char * tb_v399 = "#define PTHREAD_MUTEX_INITIALIZER 0\n"; *(const char * *)tb_grow(v_lines) = tb_v399; }
