    { const char * tb_v404 = "TB_INL void tb_outb(unsigned short port, unsigned char v) { __asm__ volatile(\"outb %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v404; }
