    { const char * tb_v904 = "    if (a < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v904; }
    { const char * tb_v905 = "    return exp(b * log(a));\n"; *(const char * *)tb_grow(v_lines) = tb_v905; }
