    { const char * tb_v1000 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1000; }
    { const char * tb_v1001 = "// блок переменных потока: начальные значения (образ от компоновщика), в конце — адрес конца\n"; *(const char * *)tb_grow(v_lines) = tb_v1001; }
    { const char * tb_v1002 = "// (так устроено у x86-64: FS указывает на конец блока, а там лежит он сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v1002; }
    { const char * tb_v1003 = "TB_API unsigned char *tb_tls_fresh(unsigned char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1003; }
    { const char * tb_v1004 = "    uint64_t n = tb_tls_size();\n"; *(const char * *)tb_grow(v_lines) = tb_v1004; }
    { const char * tb_v1005 = "    memcpy(b, tb_tls_start, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1005; }
