    { const char * tb_v1016 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v1016; }
    { const char * tb_v1017 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1017; }
    { const char * tb_v1018 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1018; }
    { const char * tb_v1019 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v1019; }
    { const char * tb_v1020 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1020; }
