    { const char * tb_v2847 = "    return tb_u8text(s + b, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
    { const char * tb_v2848 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2848; }
    { const char * tb_v2849 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2849; }
    { const char * tb_v2850 = "TB_API const char *tb_u8take(const char *s, long long *i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2850; }
    { const char * tb_v2851 = "    const unsigned char *p = (const unsigned char *)s + *i;\n"; *(const char * *)tb_grow(v_lines) = tb_v2851; }
    { const char * tb_v2852 = "    if (*p < 0x80) return tb_chr(*p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2852; }
    { const char * tb_v2853 = "    long long k = tb_u8n(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2853; }
    { const char * tb_v2854 = "    *i += k - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2854; }
