    { const char * tb_v3771 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3771; }
    { const char * tb_v3772 = "// шаг 2 — место приехало: просим принести ключ и значение\n"; *(const char * *)tb_grow(v_lines) = tb_v3772; }
