    { const char * tb_v3778 = "        __builtin_prefetch(d->vals->data + (s - 1) * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3778; }
    { const char * tb_v3779 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3779; }
    { const char * tb_v3780 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3780; }
    { const char * tb_v3781 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v3781; }
    { const char * tb_v3782 = "TB_INL void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3782; }
    { const char * tb_v3783 = "    __builtin_prefetch(l->data + i * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3783; }
