    { const char * tb_v3796 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3796; }
    { const char * tb_v3797 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3797; }
    { const char * tb_v3798 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3798; }
    { const char * tb_v3799 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3799; }
    { const char * tb_v3800 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3800; }
    { const char * tb_v3801 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3801; }
