    { const char * tb_v4016 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v4016; }
    { const char * tb_v4017 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4017; }
    { const char * tb_v4018 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4018; }
