    { const char * tb_v4134 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4134; }
    { const char * tb_v4135 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4135; }
    { const char * tb_v4136 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4136; }
