    { const char * tb_v4152 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v4152; }
    { const char * tb_v4153 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4153; }
