    { const char * tb_v4158 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4158; }
    { const char * tb_v4159 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4159; }
    { const char * tb_v4160 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4160; }
