    { const char * tb_v4165 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4165; }
    { const char * tb_v4166 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4166; }
    { const char * tb_v4167 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4167; }
    { const char * tb_v4168 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v4168; }
    { const char * tb_v4169 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v4169; }
    { const char * tb_v4170 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v4170; }
    { const char * tb_v4171 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v4171; }
    { const char * tb_v4172 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v4172; }
    { const char * tb_v4173 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v4173; }
    { const char * tb_v4174 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v4174; }
    { const char * tb_v4175 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4175; }
    { const char * tb_v4176 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v4176; }
    { const char * tb_v4177 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4177; }
    { const char * tb_v4178 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4178; }
    { const char * tb_v4179 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4179; }
