    { const char * tb_v4181 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4181; }
    { const char * tb_v4182 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v4182; }
    { const char * tb_v4183 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4183; }
    { const char * tb_v4184 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v4184; }
    { const char * tb_v4185 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4185; }
    { const char * tb_v4186 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4186; }
    { const char * tb_v4187 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v4187; }
    { const char * tb_v4188 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4188; }
    { const char * tb_v4189 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v4189; }
    { const char * tb_v4190 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v4190; }
