    { const char * tb_v4677 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4677; }
    { const char * tb_v4678 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4678; }
