    { const char * tb_v5349 = "// любой формат: по первым байтам\n"; *(const char * *)tb_grow(v_lines) = tb_v5349; }
    { const char * tb_v5350 = "TB_API uint32_t *tb_image_decode(const unsigned char *d, size_t n, int *pw, int *ph, const char **why) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5350; }
    { const char * tb_v5351 = "    if (n >= 8 && d[0] == 137 && d[1] == 'P') return tb_png(d, n, pw, ph, why);\n"; *(const char * *)tb_grow(v_lines) = tb_v5351; }
    { const char * tb_v5352 = "    if (n >= 3 && d[0] == 0xFF && d[1] == 0xD8) return tb_jpeg(d, n, pw, ph, why);\n"; *(const char * *)tb_grow(v_lines) = tb_v5352; }
    { const char * tb_v5353 = "    if (n >= 2 && d[0] == 'B' && d[1] == 'M') return tb_bmp(d, n, pw, ph, why);\n"; *(const char * *)tb_grow(v_lines) = tb_v5353; }
    { const char * tb_v5354 = "    if (n >= 4 && !memcmp(d, \"GIF8\", 4)) return tb_gif(d, n, pw, ph, why);\n"; *(const char * *)tb_grow(v_lines) = tb_v5354; }
    { const char * tb_v5355 = "    *why = \"формат картинки не знаю (умею PNG, JPEG, BMP, GIF)\";\n"; *(const char * *)tb_grow(v_lines) = tb_v5355; }
