    { const char * tb_v5357 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5357; }
    { const char * tb_v5358 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v5358; }
    { const char * tb_v5359 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v5359; }
    { const char * tb_v5360 = "TB_API tb_image *tb_imgs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5360; }
    { const char * tb_v5361 = "TB_API int tb_nimg = 0, tb_img_dirty = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5361; }
    { const char * tb_v5362 = "TB_API uint32_t *tb_imgpx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5362; }
    { const char * tb_v5363 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5363; }
    { const char * tb_v5364 = "// картинка из байтов в памяти (PNG, JPEG, BMP, GIF) → номер картинки; -1 и tb_err — не вышло\n"; *(const char * *)tb_grow(v_lines) = tb_v5364; }
    { const char * tb_v5365 = "TB_API long long tb_image_add(const unsigned char *d, size_t sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5365; }
    { const char * tb_v5366 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5366; }
    { const char * tb_v5367 = "    uint32_t *px = tb_image_decode(d, sz, &w, &h, &why);\n"; *(const char * *)tb_grow(v_lines) = tb_v5367; }
    { const char * tb_v5368 = "    if (!px) { tb_err = why; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5368; }
    { const char * tb_v5369 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5369; }
    { const char * tb_v5370 = "    if (need > 0xFFFFFFFFu) { free(px); tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5370; }
    { const char * tb_v5371 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5371; }
