    { const char * tb_v5381 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5381; }
    { const char * tb_v5382 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5382; }
    { const char * tb_v5383 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5383; }
    { const char * tb_v5384 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5384; }
    { const char * tb_v5385 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5385; }
    { const char * tb_v5386 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v5386; }
    { const char * tb_v5387 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5387; }
    { const char * tb_v5388 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5388; }
    { const char * tb_v5389 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v5389; }
    { const char * tb_v5390 = "    long long r = tb_image_add(d, (size_t)sz);\n"; *(const char * *)tb_grow(v_lines) = tb_v5390; }
    { const char * tb_v5391 = "    free(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v5391; }
