    { const char * tb_v5393 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5393; }
    { const char * tb_v5394 = "// image_from_mem(адрес, байт): картинка из памяти (файл прочитан со своего диска, пришёл по сети ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v5394; }
    { const char * tb_v5395 = "TB_API long long tb_image_from_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5395; }
    { const char * tb_v5396 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v5396; }
    { const char * tb_v5397 = "    if (!a || n <= 0) { tb_err = \"пустая память\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5397; }
    { const char * tb_v5398 = "    return tb_image_add((const unsigned char *)(uintptr_t)a, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5398; }
    { const char * tb_v5399 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5399; }
    { const char * tb_v5400 = "// image_scaled(картинка, w, h): новая картинка другого размера (уменьшение — среднее по площади,\n"; *(const char * *)tb_grow(v_lines) = tb_v5400; }
    { const char * tb_v5401 = "// увеличение — ближайшая точка). Так фото с диска влезает в окно, значок — в свой квадрат.\n"; *(const char * *)tb_grow(v_lines) = tb_v5401; }
    { const char * tb_v5402 = "TB_API long long tb_image_scaled(long long i, long long w, long long h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5402; }
    { const char * tb_v5403 = "    if (i < 0 || i >= tb_nimg) { tb_err = \"нет такой картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5403; }
    { const char * tb_v5404 = "    if (w < 1 || h < 1 || w * h > (1ll << 26)) { tb_err = \"такой размер не годится\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5404; }
    { const char * tb_v5405 = "    int sw = tb_imgs[i].w, sh = tb_imgs[i].h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5405; }
    { const char * tb_v5406 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5406; }
    { const char * tb_v5407 = "    if (need > 0xFFFFFFFFu) { tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5407; }
    { const char * tb_v5408 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5408; }
    { const char * tb_v5409 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5409; }
    { const char * tb_v5410 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v5410; }
    { const char * tb_v5411 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v5411; }
    { const char * tb_v5412 = "    if (!all || !list) { tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5412; }
    { const char * tb_v5413 = "    const uint32_t *src = tb_imgpx + tb_imgs[i].off;\n"; *(const char * *)tb_grow(v_lines) = tb_v5413; }
    { const char * tb_v5414 = "    uint32_t *dst = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5414; }
    { const char * tb_v5415 = "    for (long long y = 0; y < h; y++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5415; }
    { const char * tb_v5416 = "        int y0 = (int)(y * sh / h), y1 = (int)((y + 1) * sh / h);\n"; *(const char * *)tb_grow(v_lines) = tb_v5416; }
    { const char * tb_v5417 = "        if (y1 <= y0) y1 = y0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5417; }
    { const char * tb_v5418 = "        for (long long x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5418; }
    { const char * tb_v5419 = "            int x0 = (int)(x * sw / w), x1 = (int)((x + 1) * sw / w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5419; }
    { const char * tb_v5420 = "            if (x1 <= x0) x1 = x0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5420; }
    { const char * tb_v5421 = "            unsigned long long a = 0, r = 0, g = 0, b = 0, n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5421; }
    { const char * tb_v5422 = "            for (int yy = y0; yy < y1; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5422; }
    { const char * tb_v5423 = "                for (int xx = x0; xx < x1; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5423; }
    { const char * tb_v5424 = "                    uint32_t c = src[(size_t)yy * sw + xx];\n"; *(const char * *)tb_grow(v_lines) = tb_v5424; }
    { const char * tb_v5425 = "                    a += c >> 24; r += c >> 16 & 255; g += c >> 8 & 255; b += c & 255; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5425; }
    { const char * tb_v5426 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v5426; }
    { const char * tb_v5427 = "            dst[(size_t)y * w + x] = (uint32_t)(a / n) << 24 | (uint32_t)(r / n) << 16 | (uint32_t)(g / n) << 8 | (uint32_t)(b / n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5427; }
    { const char * tb_v5428 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5428; }
    { const char * tb_v5429 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5429; }
    { const char * tb_v5430 = "    tb_imgs[tb_nimg].w = (int)w; tb_imgs[tb_nimg].h = (int)h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5430; }
    { const char * tb_v5431 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5431; }
    { const char * tb_v5432 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5432; }
    { const char * tb_v5433 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5433; }
    { const char * tb_v5434 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5434; }
    { const char * tb_v5435 = "// снимок кадра (что нарисовано сейчас) — новая картинка; потом draw_image рисует её за один раз\n"; *(const char * *)tb_grow(v_lines) = tb_v5435; }
    { const char * tb_v5436 = "TB_API long long tb_screen_image(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5436; }
    { const char * tb_v5437 = "    if (!tb_px) { tb_err = \"окно ещё не открыто\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5437; }
    { const char * tb_v5438 = "    size_t n = (size_t)tb_gw * tb_gh, need = tb_imgpx_n + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5438; }
    { const char * tb_v5439 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5439; }
    { const char * tb_v5440 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5440; }
    { const char * tb_v5441 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v5441; }
    { const char * tb_v5442 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v5442; }
    { const char * tb_v5443 = "    if (!all || !list) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5443; }
    { const char * tb_v5444 = "    for (size_t i = 0; i < n; i++) tb_imgpx[tb_imgpx_n + i] = tb_px[i] | 0xFF000000u;\n"; *(const char * *)tb_grow(v_lines) = tb_v5444; }
    { const char * tb_v5445 = "    tb_imgs[tb_nimg].w = tb_gw; tb_imgs[tb_nimg].h = tb_gh; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5445; }
    { const char * tb_v5446 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5446; }
    { const char * tb_v5447 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5447; }
    { const char * tb_v5448 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5448; }
    { const char * tb_v5449 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5449; }
    { const char * tb_v5450 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5450; }
    { const char * tb_v5451 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5451; }
    { const char * tb_v5452 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5452; }
    { const char * tb_v5453 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v5453; }
    { const char * tb_v5454 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v5454; }
    { const char * tb_v5455 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5455; }
    { const char * tb_v5456 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5456; }
    { const char * tb_v5457 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5457; }
    { const char * tb_v5458 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5458; }
    { const char * tb_v5459 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5459; }
    { const char * tb_v5460 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5460; }
    { const char * tb_v5461 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5461; }
    { const char * tb_v5462 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5462; }
    { const char * tb_v5463 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5463; }
    { const char * tb_v5464 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5464; }
    { const char * tb_v5465 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v5465; }
    { const char * tb_v5466 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5466; }
