    { const char * tb_v5511 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5511; }
    { const char * tb_v5512 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5512; }
