    { const char * tb_v5555 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5555; }
    { const char * tb_v5556 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5556; }
    { const char * tb_v5557 = "    double dx = x0 - 2 * cx + x1, dy = y0 - 2 * cy + y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5557; }
    { const char * tb_v5558 = "    int n = 1 + (int)sqrt(sqrt(dx * dx + dy * dy) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5558; }
    { const char * tb_v5559 = "    if (n > 16) n = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v5559; }
    { const char * tb_v5560 = "    double px = x0, py = y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5560; }
