    { const char * tb_v5564 = "        tb_edge(E, px, py, qx, qy);\n"; *(const char * *)tb_grow(v_lines) = tb_v5564; }
    { const char * tb_v5565 = "        px = qx; py = qy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5565; }
    { const char * tb_v5566 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5566; }
    { const char * tb_v5567 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5567; }
    { const char * tb_v5568 = "static void tb_ttf_outline(const tb_font_t *f, unsigned g, const double *m, tb_edges *E, int depth) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5568; }
    { const char * tb_v5569 = "    size_t len, o = tb_ttf_gpos(f, g, &len);\n"; *(const char * *)tb_grow(v_lines) = tb_v5569; }
