    { const char * tb_v5579 = "            else { if (fl & 2) { dx = (int8_t)f->d[p]; dy = (int8_t)f->d[p + 1]; } p += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5579; }
