    { const char * tb_v5743 = "    for (int j = 0; j < h; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5743; }
    { const char * tb_v5744 = "        float sum = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5744; }
    { const char * tb_v5745 = "        const float *row = acc + (size_t)j * (w + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5745; }
    { const char * tb_v5746 = "        for (int i = 0; i < w; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5746; }
    { const char * tb_v5747 = "            sum += row[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5747; }
    { const char * tb_v5748 = "            float a = sum < 0 ? -sum : sum;\n"; *(const char * *)tb_grow(v_lines) = tb_v5748; }
