    { const char * tb_v5903 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5903; }
    { const char * tb_v5904 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5904; }
    { const char * tb_v5905 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v5905; }
