    { const char * tb_v5942 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5942; }
    { const char * tb_v5943 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5943; }
    { const char * tb_v5944 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5944; }
    { const char * tb_v5945 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v5945; }
