    { const char * tb_v5951 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (1u << 29) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5951; }
    { const char * tb_v5952 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5952; }
    { const char * tb_v5953 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v5953; }
    { const char * tb_v5954 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v5954; }
