    { const char * tb_v5958 = "// треугольник сетки (3D): как треугольник, плюс плоскость глубины в tb_gplane\n"; *(const char * *)tb_grow(v_lines) = tb_v5958; }
    { const char * tb_v5959 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5959; }
    { const char * tb_v5960 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5960; }
    { const char * tb_v5961 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin);\n"; *(const char * *)tb_grow(v_lines) = tb_v5961; }
