    { const char * tb_v7916 = "// Экран и мышь Омниума (tb bare + рисование): видеокарта QEMU/Bochs, мышь PS/2 и vmmouse.\n"; *(const char * *)tb_grow(v_lines) = tb_v7916; }
    { const char * tb_v7917 = "// Вставляется в compiler/runtime.h на место строки //@include (tools/embed_runtime.py).\n"; *(const char * *)tb_grow(v_lines) = tb_v7917; }
    { const char * tb_v7918 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7918; }
    { const char * tb_v7919 = "// ---------- экран и мышь в ядре (tb bare) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7919; }
    { const char * tb_v7920 = "// Экран: видеокарта Bochs/QEMU (BGA, «-vga std»): режим w×h, 32 бита на точку, буфер кадра в памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v7920; }
    { const char * tb_v7921 = "// Где буфер — говорит шина PCI (BAR0). Кадр рисуется в tb_px, на экран копируется целиком.\n"; *(const char * *)tb_grow(v_lines) = tb_v7921; }
    { const char * tb_v7922 = "// Мышь PS/2 (прерывание 12), клавиатура — та же, что для read_key.\n"; *(const char * *)tb_grow(v_lines) = tb_v7922; }
    { const char * tb_v7923 = "TB_API volatile uint32_t *tb_lfb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7923; }
    { const char * tb_v7924 = "TB_API int tb_bcur = 0;          // курсор: 0 стрелка ... 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v7924; }
    { const char * tb_v7925 = "TB_API char *tb_bclip = 0;       // буфер обмена — просто текст в памяти ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v7925; }
    { const char * tb_v7926 = "TB_API unsigned tb_pci_r(int bus, int dev, int fn, int off) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7926; }
    { const char * tb_v7927 = "    tb_outl(0xCF8, 0x80000000u | (unsigned)bus << 16 | (unsigned)dev << 11 | (unsigned)fn << 8 | (unsigned)(off & 0xFC));\n"; *(const char * *)tb_grow(v_lines) = tb_v7927; }
    { const char * tb_v7928 = "    return tb_inl(0xCFC);\n"; *(const char * *)tb_grow(v_lines) = tb_v7928; }
