    { const char * tb_v7930 = "TB_API uint64_t tb_bga_find(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7930; }
    { const char * tb_v7931 = "    for (int bus = 0; bus < 8; bus++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7931; }
    { const char * tb_v7932 = "        for (int dev = 0; dev < 32; dev++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7932; }
    { const char * tb_v7933 = "            unsigned id = tb_pci_r(bus, dev, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7933; }
    { const char * tb_v7934 = "            if (id == 0x11111234u || id == 0xBEEF80EEu) return tb_pci_r(bus, dev, 0, 0x10) & ~0xFu;\n"; *(const char * *)tb_grow(v_lines) = tb_v7934; }
    { const char * tb_v7935 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7935; }
    { const char * tb_v7936 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7936; }
    { const char * tb_v7937 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7937; }
    { const char * tb_v7938 = "TB_API void tb_bga_w(unsigned short i, unsigned short v) { tb_outw(0x1CE, i); tb_outw(0x1CF, v); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7938; }
    { const char * tb_v7939 = "TB_API unsigned short tb_bga_r(unsigned short i) { tb_outw(0x1CE, i); return tb_inw(0x1CF); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7939; }
    { const char * tb_v7940 = "// окно устройства в страницы (по 2 МБ, писать можно, без кэша чтения)\n"; *(const char * *)tb_grow(v_lines) = tb_v7940; }
    { const char * tb_v7941 = "TB_API void tb_map_dev(uint64_t a, uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7941; }
    { const char * tb_v7942 = "    for (uint64_t p = a & ~0x1FFFFFull; p < a + n; p += 0x200000ull) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7942; }
