    { const char * tb_v7946 = "        __asm__ volatile(\"invlpg (%0)\" : : \"r\"(p) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7946; }
    { const char * tb_v7947 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7947; }
    { const char * tb_v7948 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7948; }
    { const char * tb_v7949 = "// --- клавиши для key_down / typed_text (набор 1, как шлёт контроллер клавиатуры) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v7949; }
    { const char * tb_v7950 = "TB_API int tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7950; }
    { const char * tb_v7951 = "TB_API int tb_sc_key(unsigned char sc, int ext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7951; }
    { const char * tb_v7952 = "    if (ext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7952; }
    { const char * tb_v7953 = "        switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7953; }
    { const char * tb_v7954 = "        case 0x48: return TB_K_UP; case 0x50: return TB_K_DOWN; case 0x4D: return TB_K_RIGHT; case 0x4B: return TB_K_LEFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7954; }
    { const char * tb_v7955 = "        case 0x53: return TB_K_DEL; case 0x47: return TB_K_HOME; case 0x4F: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v7955; }
    { const char * tb_v7956 = "        case 0x49: return TB_K_PGUP; case 0x51: return TB_K_PGDN; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7956; }
    { const char * tb_v7957 = "        case 0x1C: return TB_K_ENTER;\n"; *(const char * *)tb_grow(v_lines) = tb_v7957; }
    { const char * tb_v7958 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7958; }
    { const char * tb_v7959 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7959; }
    { const char * tb_v7960 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7960; }
    { const char * tb_v7961 = "    switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7961; }
    { const char * tb_v7962 = "    case 0x1C: return TB_K_ENTER; case 0x01: return TB_K_ESC; case 0x39: return TB_K_SPACE; case 0x0E: return TB_K_BACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v7962; }
    { const char * tb_v7963 = "    case 0x0F: return TB_K_TAB; case 0x2A: case 0x36: return TB_K_SHIFT; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7963; }
    { const char * tb_v7964 = "    case 0x57: return TB_K_F1 + 10; case 0x58: return TB_K_F1 + 11;\n"; *(const char * *)tb_grow(v_lines) = tb_v7964; }
    { const char * tb_v7965 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7965; }
    { const char * tb_v7966 = "    if (sc >= 0x3B && sc <= 0x44) return TB_K_F1 + (sc - 0x3B);\n"; *(const char * *)tb_grow(v_lines) = tb_v7966; }
    { const char * tb_v7967 = "    if (sc < 58) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7967; }
    { const char * tb_v7968 = "        int ch = (unsigned char)tb_kmap[0][sc];\n"; *(const char * *)tb_grow(v_lines) = tb_v7968; }
    { const char * tb_v7969 = "        if (ch >= 'a' && ch <= 'z') return ch - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7969; }
    { const char * tb_v7970 = "        if (ch >= '0' && ch <= '9') return ch;\n"; *(const char * *)tb_grow(v_lines) = tb_v7970; }
    { const char * tb_v7971 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7971; }
    { const char * tb_v7972 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7972; }
    { const char * tb_v7973 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7973; }
    { const char * tb_v7974 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7974; }
    { const char * tb_v7975 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7975; }
    { const char * tb_v7976 = "    int up = sc & 0x80, ext = tb_kext;\n"; *(const char * *)tb_grow(v_lines) = tb_v7976; }
    { const char * tb_v7977 = "    tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7977; }
    { const char * tb_v7978 = "    sc &= 0x7F;\n"; *(const char * *)tb_grow(v_lines) = tb_v7978; }
    { const char * tb_v7979 = "    int k = tb_sc_key(sc, ext);\n"; *(const char * *)tb_grow(v_lines) = tb_v7979; }
    { const char * tb_v7980 = "    if (k) { tb_keys[k] = !up; if (!up) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7980; }
    { const char * tb_v7981 = "    if (!up && !ext && sc < 58 && !tb_keys[TB_K_CTRL]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7981; }
    { const char * tb_v7982 = "        char ch = tb_kmap[tb_keys[TB_K_SHIFT] ? 1 : 0][sc];\n"; *(const char * *)tb_grow(v_lines) = tb_v7982; }
    { const char * tb_v7983 = "        if ((unsigned char)ch >= 32) tb_type_cp((unsigned char)ch);\n"; *(const char * *)tb_grow(v_lines) = tb_v7983; }
    { const char * tb_v7984 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7984; }
    { const char * tb_v7985 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7985; }
    { const char * tb_v7986 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v7986; }
    { const char * tb_v7987 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7987; }
    { const char * tb_v7988 = "TB_API int tb_mpn = 0, tb_mpsize = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v7988; }
    { const char * tb_v7989 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v7989; }
    { const char * tb_v7990 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7990; }
    { const char * tb_v7991 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v7991; }
    { const char * tb_v7992 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7992; }
    { const char * tb_v7993 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7993; }
    { const char * tb_v7994 = "TB_API int tb_mouse_cmd(unsigned char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7994; }
    { const char * tb_v7995 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xD4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7995; }
    { const char * tb_v7996 = "    tb_ps2_wait_in(); tb_outb(0x60, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7996; }
    { const char * tb_v7997 = "    return tb_ps2_read();   // 0xFA — принято\n"; *(const char * *)tb_grow(v_lines) = tb_v7997; }
    { const char * tb_v7998 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7998; }
    { const char * tb_v7999 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v7999; }
    { const char * tb_v8000 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v8000; }
    { const char * tb_v8001 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8001; }
    { const char * tb_v8002 = "TB_API void tb_vmm_call(uint32_t cmd, uint32_t arg, uint32_t r[4]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8002; }
    { const char * tb_v8003 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v8003; }
    { const char * tb_v8004 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8004; }
    { const char * tb_v8005 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8005; }
    { const char * tb_v8006 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8006; }
    { const char * tb_v8007 = "TB_API void tb_vmm_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8007; }
    { const char * tb_v8008 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v8008; }
    { const char * tb_v8009 = "    tb_vmm_call(10, 0, r);                               // «кто здесь»: в ответе ebx — тот же магический номер\n"; *(const char * *)tb_grow(v_lines) = tb_v8009; }
    { const char * tb_v8010 = "    if (r[1] != 0x564D5868u) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8010; }
    { const char * tb_v8011 = "    tb_vmm_call(41, 0x45414552u, r);                     // включить\n"; *(const char * *)tb_grow(v_lines) = tb_v8011; }
    { const char * tb_v8012 = "    tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8012; }
    { const char * tb_v8013 = "    if (r[0] == 0xFFFF0000u || (r[0] & 0xFFFF) == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8013; }
    { const char * tb_v8014 = "    tb_vmm_call(39, 1, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8014; }
    { const char * tb_v8015 = "    if (r[0] != 0x3442554Au) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8015; }
    { const char * tb_v8016 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v8016; }
    { const char * tb_v8017 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8017; }
    { const char * tb_v8018 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8018; }
    { const char * tb_v8019 = "TB_API void tb_vmm_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8019; }
    { const char * tb_v8020 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v8020; }
    { const char * tb_v8021 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8021; }
    { const char * tb_v8022 = "        tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8022; }
    { const char * tb_v8023 = "        if (r[0] == 0xFFFF0000u) { tb_vmm = 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8023; }
    { const char * tb_v8024 = "        if ((r[0] & 0xFFFF) < 4) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8024; }
    { const char * tb_v8025 = "        tb_vmm_call(39, 4, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8025; }
    { const char * tb_v8026 = "        tb_mx = (int)((uint64_t)r[1] * (uint64_t)tb_gw / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v8026; }
    { const char * tb_v8027 = "        tb_my = (int)((uint64_t)r[2] * (uint64_t)tb_gh / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v8027; }
    { const char * tb_v8028 = "        int down = (r[0] & 0x20) != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8028; }
    { const char * tb_v8029 = "        if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8029; }
    { const char * tb_v8030 = "        tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v8030; }
