    { const char * tb_v8033 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8033; }
    { const char * tb_v8034 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8034; }
    { const char * tb_v8035 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8035; }
    { const char * tb_v8036 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v8036; }
    { const char * tb_v8037 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8037; }
