    { const char * tb_v8039 = "    if (!(st & 0x20)) { tb_key_byte(b); return; }   // байт клавиатуры пришёл сюда\n"; *(const char * *)tb_grow(v_lines) = tb_v8039; }
    { const char * tb_v8040 = "    if (tb_vmm) { tb_vmm_read(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8040; }
    { const char * tb_v8041 = "    if (tb_mpn == 0 && !(b & 8)) return;           // первый байт пакета всегда с битом 3\n"; *(const char * *)tb_grow(v_lines) = tb_v8041; }
