    { const char * tb_v9027 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v9027; }
    { const char * tb_v9028 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v9028; }
