    { const char * tb_v9032 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v9032; }
