    { const char * tb_v9047 = "    Atom utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False), targets = XInternAtom(tb_dpy, \"TARGETS\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v9047; }
    { const char * tb_v9048 = "    XSelectionEvent ev;\n"; *(const char * *)tb_grow(v_lines) = tb_v9048; }
