    { const char * tb_v9054 = "        Atom list[3] = { targets, utf8, XA_STRING };\n"; *(const char * *)tb_grow(v_lines) = tb_v9054; }
    { const char * tb_v9055 = "        XChangeProperty(tb_dpy, r->requestor, prop, XA_ATOM, 32, PropModeReplace, (unsigned char *)list, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v9055; }
    { const char * tb_v9056 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v9056; }
