    { const char * tb_v9070 = "TB_API char *tb_gfx_clip_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9070; }
    { const char * tb_v9071 = "    if (!tb_dpy) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9071; }
