    { const char * tb_v9126 = "                if (!(e.xkey.state & ControlMask)) tb_type_cp(tb_x_uni(ks));\n"; *(const char * *)tb_grow(v_lines) = tb_v9126; }
    { const char * tb_v9127 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9127; }
    { const char * tb_v9128 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9128; }
    { const char * tb_v9129 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9129; }
    { const char * tb_v9130 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v9130; }
    { const char * tb_v9131 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9131; }
