    { const char * tb_v9141 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v9141; }
    { const char * tb_v9142 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v9142; }
    { const char * tb_v9143 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v9143; }
    { const char * tb_v9144 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v9144; }
    { const char * tb_v9145 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v9145; }
    { const char * tb_v9146 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v9146; }
    { const char * tb_v9147 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9147; }
    { const char * tb_v9148 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9148; }
    { const char * tb_v9149 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9149; }
    { const char * tb_v9150 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9150; }
    { const char * tb_v9151 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9151; }
    { const char * tb_v9152 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v9152; }
    { const char * tb_v9153 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9153; }
    { const char * tb_v9154 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v9154; }
    { const char * tb_v9155 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v9155; }
    { const char * tb_v9156 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v9156; }
    { const char * tb_v9157 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9157; }
    { const char * tb_v9158 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9158; }
    { const char * tb_v9159 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v9159; }
    { const char * tb_v9160 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v9160; }
    { const char * tb_v9161 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v9161; }
    { const char * tb_v9162 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9162; }
    { const char * tb_v9163 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9163; }
    { const char * tb_v9164 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9164; }
    { const char * tb_v9165 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9165; }
    { const char * tb_v9166 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9166; }
    { const char * tb_v9167 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v9167; }
    { const char * tb_v9168 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9168; }
    { const char * tb_v9169 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v9169; }
    { const char * tb_v9170 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v9170; }
    { const char * tb_v9171 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9171; }
    { const char * tb_v9172 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9172; }
    { const char * tb_v9173 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9173; }
    { const char * tb_v9174 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9174; }
    { const char * tb_v9175 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9175; }
    { const char * tb_v9176 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9176; }
    { const char * tb_v9177 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9177; }
    { const char * tb_v9178 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9178; }
    { const char * tb_v9179 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9179; }
    { const char * tb_v9180 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9180; }
    { const char * tb_v9181 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9181; }
    { const char * tb_v9182 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9182; }
    { const char * tb_v9183 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9183; }
    { const char * tb_v9184 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v9184; }
    { const char * tb_v9185 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9185; }
    { const char * tb_v9186 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v9186; }
    { const char * tb_v9187 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v9187; }
    { const char * tb_v9188 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9188; }
    { const char * tb_v9189 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9189; }
    { const char * tb_v9190 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9190; }
    { const char * tb_v9191 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9191; }
    { const char * tb_v9192 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v9192; }
    { const char * tb_v9193 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9193; }
    { const char * tb_v9194 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9194; }
    { const char * tb_v9195 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9195; }
    { const char * tb_v9196 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9196; }
    { const char * tb_v9197 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v9197; }
    { const char * tb_v9198 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v9198; }
    { const char * tb_v9199 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v9199; }
    { const char * tb_v9200 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9200; }
    { const char * tb_v9201 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9201; }
    { const char * tb_v9202 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9202; }
    { const char * tb_v9203 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9203; }
    { const char * tb_v9204 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9204; }
    { const char * tb_v9205 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9205; }
    { const char * tb_v9206 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v9206; }
    { const char * tb_v9207 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9207; }
    { const char * tb_v9208 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v9208; }
    { const char * tb_v9209 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9209; }
    { const char * tb_v9210 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9210; }
    { const char * tb_v9211 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9211; }
    { const char * tb_v9212 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9212; }
    { const char * tb_v9213 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9213; }
    { const char * tb_v9214 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9214; }
    { const char * tb_v9215 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9215; }
    { const char * tb_v9216 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9216; }
    { const char * tb_v9217 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v9217; }
    { const char * tb_v9218 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9218; }
    { const char * tb_v9219 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v9219; }
    { const char * tb_v9220 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v9220; }
    { const char * tb_v9221 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9221; }
    { const char * tb_v9222 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9222; }
