    { const char * tb_v9246 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9246; }
    { const char * tb_v9247 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v9247; }
    { const char * tb_v9248 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9248; }
    { const char * tb_v9249 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9249; }
