    { const char * tb_v9254 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9254; }
    { const char * tb_v9255 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9255; }
    { const char * tb_v9256 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9256; }
