    { const char * tb_v9259 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v9259; }
    { const char * tb_v9260 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v9260; }
    { const char * tb_v9261 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v9261; }
    { const char * tb_v9262 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v9262; }
