    { const char * tb_v9274 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9274; }
    { const char * tb_v9275 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v9275; }
