    { const char * tb_v9287 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9287; }
    { const char * tb_v9288 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v9288; }
    { const char * tb_v9289 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9289; }
    { const char * tb_v9290 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v9290; }
    { const char * tb_v9291 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v9291; }
    { const char * tb_v9292 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v9292; }
    { const char * tb_v9293 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v9293; }
