    { const char * tb_v9307 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9307; }
    { const char * tb_v9308 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v9308; }
    { const char * tb_v9309 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9309; }
    { const char * tb_v9310 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9310; }
    { const char * tb_v9311 = "    uint32_t a = 255 - ((c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9311; }
