    { const char * tb_v9315 = "    *p = a >= 255 ? (c & 0xFFFFFF) : tb_mix(*p, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v9315; }
    { const char * tb_v9316 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9316; }
    { const char * tb_v9317 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v9317; }
    { const char * tb_v9318 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v9318; }
    { const char * tb_v9319 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9319; }
    { const char * tb_v9320 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9320; }
    { const char * tb_v9321 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9321; }
    { const char * tb_v9322 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9322; }
    { const char * tb_v9323 = "    if (tb_gpu_on) {                                   // видеокарта: слоями (без сглаживания)\n"; *(const char * *)tb_grow(v_lines) = tb_v9323; }
