    { const char * tb_v9325 = "            double f = 1.0 - (double)k / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9325; }
    { const char * tb_v9326 = "            long long a = (long long)((255 - ((c >> 24) & 255)) * f * f / (size / 2.0) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9326; }
    { const char * tb_v9327 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v9327; }
    { const char * tb_v9328 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9328; }
    { const char * tb_v9329 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9329; }
    { const char * tb_v9330 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9330; }
    { const char * tb_v9331 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9331; }
    { const char * tb_v9332 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9332; }
    { const char * tb_v9333 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9333; }
    { const char * tb_v9334 = "        double py = j + 0.5, dy = fabs(py - cy) - (hh - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v9334; }
    { const char * tb_v9335 = "        if (dy < 0) dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9335; }
    { const char * tb_v9336 = "        long long xa = x - size < 0 ? 0 : x - size, xb = x + w + size > tb_gw ? tb_gw : x + w + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9336; }
    { const char * tb_v9337 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9337; }
    { const char * tb_v9338 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v9338; }
    { const char * tb_v9339 = "            if (dx < 0) dx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9339; }
    { const char * tb_v9340 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9340; }
    { const char * tb_v9341 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9341; }
