    { const char * tb_v9350 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v9350; }
    { const char * tb_v9351 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9351; }
    { const char * tb_v9352 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v9352; }
    { const char * tb_v9353 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9353; }
    { const char * tb_v9354 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9354; }
