    { const char * tb_v9363 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9363; }
    { const char * tb_v9364 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v9364; }
    { const char * tb_v9365 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9365; }
    { const char * tb_v9366 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9366; }
    { const char * tb_v9367 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v9367; }
    { const char * tb_v9368 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9368; }
    { const char * tb_v9369 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9369; }
    { const char * tb_v9370 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9370; }
    { const char * tb_v9371 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v9371; }
    { const char * tb_v9372 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9372; }
    { const char * tb_v9373 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9373; }
    { const char * tb_v9374 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9374; }
    { const char * tb_v9375 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9375; }
    { const char * tb_v9376 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9376; }
    { const char * tb_v9377 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9377; }
    { const char * tb_v9378 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9378; }
    { const char * tb_v9379 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9379; }
    { const char * tb_v9380 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9380; }
