    { const char * tb_v9402 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9402; }
    { const char * tb_v9403 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v9403; }
    { const char * tb_v9404 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9404; }
    { const char * tb_v9405 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9405; }
    { const char * tb_v9406 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v9406; }
    { const char * tb_v9407 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9407; }
    { const char * tb_v9408 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v9408; }
    { const char * tb_v9409 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9409; }
    { const char * tb_v9410 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9410; }
    { const char * tb_v9411 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9411; }
    { const char * tb_v9412 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9412; }
    { const char * tb_v9413 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9413; }
    { const char * tb_v9414 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v9414; }
    { const char * tb_v9415 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v9415; }
    { const char * tb_v9416 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9416; }
    { const char * tb_v9417 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9417; }
    { const char * tb_v9418 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9418; }
    { const char * tb_v9419 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9419; }
    { const char * tb_v9420 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9420; }
    { const char * tb_v9421 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9421; }
    { const char * tb_v9422 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v9422; }
    { const char * tb_v9423 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v9423; }
    { const char * tb_v9424 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9424; }
    { const char * tb_v9425 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9425; }
    { const char * tb_v9426 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9426; }
    { const char * tb_v9427 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9427; }
    { const char * tb_v9428 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9428; }
    { const char * tb_v9429 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9429; }
    { const char * tb_v9430 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9430; }
    { const char * tb_v9431 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9431; }
    { const char * tb_v9432 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9432; }
    { const char * tb_v9433 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9433; }
    { const char * tb_v9434 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v9434; }
    { const char * tb_v9435 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9435; }
    { const char * tb_v9436 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9436; }
    { const char * tb_v9437 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9437; }
    { const char * tb_v9438 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9438; }
    { const char * tb_v9439 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v9439; }
    { const char * tb_v9440 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v9440; }
    { const char * tb_v9441 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9441; }
    { const char * tb_v9442 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9442; }
    { const char * tb_v9443 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9443; }
    { const char * tb_v9444 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9444; }
    { const char * tb_v9445 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9445; }
    { const char * tb_v9446 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9446; }
    { const char * tb_v9447 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9447; }
    { const char * tb_v9448 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9448; }
    { const char * tb_v9449 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v9449; }
    { const char * tb_v9450 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v9450; }
    { const char * tb_v9451 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9451; }
    { const char * tb_v9452 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9452; }
    { const char * tb_v9453 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9453; }
    { const char * tb_v9454 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9454; }
    { const char * tb_v9455 = "                long long fx = xx * 128 - 64; if (fx < 0) fx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9455; }
    { const char * tb_v9456 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v9456; }
    { const char * tb_v9457 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9457; }
    { const char * tb_v9458 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9458; }
    { const char * tb_v9459 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9459; }
    { const char * tb_v9460 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9460; }
    { const char * tb_v9461 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v9461; }
    { const char * tb_v9462 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v9462; }
    { const char * tb_v9463 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9463; }
    { const char * tb_v9464 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9464; }
    { const char * tb_v9465 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9465; }
    { const char * tb_v9466 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9466; }
    { const char * tb_v9467 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9467; }
    { const char * tb_v9468 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9468; }
    { const char * tb_v9469 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9469; }
    { const char * tb_v9470 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9470; }
    { const char * tb_v9471 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9471; }
    { const char * tb_v9472 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9472; }
    { const char * tb_v9473 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9473; }
    { const char * tb_v9474 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9474; }
    { const char * tb_v9475 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9475; }
