    { const char * tb_v9477 = "                if ((c >> 24) & 255) { uint32_t *p = &tb_px[(cy + j) * tb_gw + cx + i]; *p = tb_mix(*p, (uint32_t)c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9477; }
