    { const char * tb_v9481 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9481; }
    { const char * tb_v9482 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9482; }
    { const char * tb_v9483 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9483; }
    { const char * tb_v9484 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9484; }
    { const char * tb_v9485 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9485; }
    { const char * tb_v9486 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v9486; }
    { const char * tb_v9487 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9487; }
    { const char * tb_v9488 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v9488; }
    { const char * tb_v9489 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9489; }
    { const char * tb_v9490 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v9490; }
    { const char * tb_v9491 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v9491; }
    { const char * tb_v9492 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9492; }
    { const char * tb_v9493 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9493; }
    { const char * tb_v9494 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9494; }
    { const char * tb_v9495 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9495; }
    { const char * tb_v9496 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v9496; }
    { const char * tb_v9497 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9497; }
    { const char * tb_v9498 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9498; }
    { const char * tb_v9499 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v9499; }
    { const char * tb_v9500 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v9500; }
    { const char * tb_v9501 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v9501; }
    { const char * tb_v9502 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v9502; }
    { const char * tb_v9503 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9503; }
    { const char * tb_v9504 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v9504; }
    { const char * tb_v9505 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9505; }
    { const char * tb_v9506 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9506; }
    { const char * tb_v9507 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9507; }
    { const char * tb_v9508 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9508; }
    { const char * tb_v9509 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9509; }
    { const char * tb_v9510 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9510; }
    { const char * tb_v9511 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9511; }
    { const char * tb_v9512 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9512; }
    { const char * tb_v9513 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9513; }
    { const char * tb_v9514 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9514; }
    { const char * tb_v9515 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9515; }
    { const char * tb_v9516 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9516; }
    { const char * tb_v9517 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9517; }
    { const char * tb_v9518 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9518; }
    { const char * tb_v9519 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9519; }
    { const char * tb_v9520 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v9520; }
    { const char * tb_v9521 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v9521; }
    { const char * tb_v9522 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9522; }
    { const char * tb_v9523 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v9523; }
    { const char * tb_v9524 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v9524; }
    { const char * tb_v9525 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9525; }
    { const char * tb_v9526 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9526; }
    { const char * tb_v9527 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v9527; }
    { const char * tb_v9528 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9528; }
    { const char * tb_v9529 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9529; }
    { const char * tb_v9530 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9530; }
    { const char * tb_v9531 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v9531; }
    { const char * tb_v9532 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v9532; }
    { const char * tb_v9533 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v9533; }
    { const char * tb_v9534 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9534; }
    { const char * tb_v9535 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9535; }
    { const char * tb_v9536 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9536; }
    { const char * tb_v9537 = "    long long W = (16777216 - (long long)d) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v9537; }
    { const char * tb_v9538 = "    if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9538; }
    { const char * tb_v9539 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v9539; }
    { const char * tb_v9540 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v9540; }
    { const char * tb_v9541 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v9541; }
    { const char * tb_v9542 = "    v -= tb_fdiv(v, tx->h) * (long long)tx->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9542; }
    { const char * tb_v9543 = "    *out = tb_imgpx[tx->off + (uint32_t)v * tx->w + (uint32_t)u];\n"; *(const char * *)tb_grow(v_lines) = tb_v9543; }
    { const char * tb_v9544 = "    return (*out >> 24) >= 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v9544; }
    { const char * tb_v9545 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9545; }
    { const char * tb_v9546 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v9546; }
    { const char * tb_v9547 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9547; }
    { const char * tb_v9548 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v9548; }
    { const char * tb_v9549 = "             b = ((t & 255) * (c & 255) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9549; }
    { const char * tb_v9550 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9550; }
    { const char * tb_v9551 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9551; }
    { const char * tb_v9552 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9552; }
    { const char * tb_v9553 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9553; }
    { const char * tb_v9554 = "    const tb_gtex_t *tx = pl ? tb_tex_cur : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9554; }
    { const char * tb_v9555 = "    if (gpu) { if (tx) tb_gpu_tri3t(t, c, pl, tx); else if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9555; }
    { const char * tb_v9556 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9556; }
    { const char * tb_v9557 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9557; }
    { const char * tb_v9558 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9558; }
    { const char * tb_v9559 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9559; }
    { const char * tb_v9560 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9560; }
    { const char * tb_v9561 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9561; }
    { const char * tb_v9562 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9562; }
    { const char * tb_v9563 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9563; }
    { const char * tb_v9564 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9564; }
    { const char * tb_v9565 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9565; }
    { const char * tb_v9566 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9566; }
    { const char * tb_v9567 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9567; }
    { const char * tb_v9568 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9568; }
    { const char * tb_v9569 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9569; }
    { const char * tb_v9570 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v9570; }
    { const char * tb_v9571 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9571; }
    { const char * tb_v9572 = "                    uint32_t col = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9572; }
    { const char * tb_v9573 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v9573; }
    { const char * tb_v9574 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v9574; }
    { const char * tb_v9575 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9575; }
    { const char * tb_v9576 = "                        if (tx) {   // картинка: прозрачная точка (меньше 128) — дырка, глубину не пишет\n"; *(const char * *)tb_grow(v_lines) = tb_v9576; }
    { const char * tb_v9577 = "                            uint32_t tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v9577; }
    { const char * tb_v9578 = "                            if (!tb_tex_px(tx, d, x, y, &tp)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9578; }
    { const char * tb_v9579 = "                            col = tb_tex_tint(tp, col);\n"; *(const char * *)tb_grow(v_lines) = tb_v9579; }
    { const char * tb_v9580 = "                        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9580; }
    { const char * tb_v9581 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9581; }
    { const char * tb_v9582 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9582; }
    { const char * tb_v9583 = "                    tb_px[y * tb_gw + x] = col;\n"; *(const char * *)tb_grow(v_lines) = tb_v9583; }
    { const char * tb_v9584 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v9584; }
    { const char * tb_v9585 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9585; }
    { const char * tb_v9586 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9586; }
    { const char * tb_v9587 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9587; }
    { const char * tb_v9588 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v9588; }
    { const char * tb_v9589 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v9589; }
    { const char * tb_v9590 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v9590; }
    { const char * tb_v9591 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v9591; }
    { const char * tb_v9592 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9592; }
    { const char * tb_v9593 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9593; }
    { const char * tb_v9594 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v9594; }
    { const char * tb_v9595 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9595; }
    { const char * tb_v9596 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9596; }
    { const char * tb_v9597 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9597; }
    { const char * tb_v9598 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9598; }
    { const char * tb_v9599 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9599; }
    { const char * tb_v9600 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9600; }
    { const char * tb_v9601 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v9601; }
    { const char * tb_v9602 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9602; }
    { const char * tb_v9603 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v9603; }
    { const char * tb_v9604 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9604; }
    { const char * tb_v9605 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9605; }
    { const char * tb_v9606 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9606; }
    { const char * tb_v9607 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9607; }
    { const char * tb_v9608 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v9608; }
    { const char * tb_v9609 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9609; }
