    { const char * tb_v9687 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9687; }
    { const char * tb_v9688 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v9688; }
    { const char * tb_v9689 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v9689; }
    { const char * tb_v9690 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v9690; }
