    { const char * tb_v9719 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v9719; }
    { const char * tb_v9720 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v9720; }
