    { const char * tb_v9932 = "    tx->au = pu[0]; tx->bu = pu[1]; tx->cu = pu[2]; tx->av = pv[0]; tx->bv = pv[1]; tx->cv = pv[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9932; }
    { const char * tb_v9933 = "    tx->off = im->off; tx->w = (uint32_t)im->w; tx->h = (uint32_t)im->h; tx->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9933; }
    { const char * tb_v9934 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9934; }
