    { const char * tb_v9936 = "static void tb_tex_rec_d(const tb_mesh *m, int n, const double *sx, const double *sy, const double *dd, const double *uu, const double *vv, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9936; }
