    { const char * tb_v9945 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0], area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v9945; }
    { const char * tb_v9946 = "    double *S[2] = { su, sv };\n"; *(const char * *)tb_grow(v_lines) = tb_v9946; }
    { const char * tb_v9947 = "    int64_t o[6];\n"; *(const char * *)tb_grow(v_lines) = tb_v9947; }
