    { const char * tb_v9949 = "        double ax = 0, by = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9949; }
    { const char * tb_v9950 = "        if (fabs(area) >= 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9950; }
