    { const char * tb_v9963 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9963; }
    { const char * tb_v9964 = "// R — поворот сетки (3 × 3): угол p в мире = R p + (x, y, z)\n"; *(const char * *)tb_grow(v_lines) = tb_v9964; }
    { const char * tb_v9965 = "static void tb_draw_mesh_d(tb_mesh *m, double x, double y, double z, double R[3][3], const int32_t *L, long long t0, long long t1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9965; }
    { const char * tb_v9966 = "    if (m->nv > tb_3vcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9966; }
