    { const char * tb_v9984 = "        double wx = R[0][0] * p[0] + R[0][1] * p[1] + R[0][2] * p[2] + x - tb_cam[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9984; }
    { const char * tb_v9985 = "        double wy = R[1][0] * p[0] + R[1][1] * p[1] + R[1][2] * p[2] + y - tb_cam[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9985; }
    { const char * tb_v9986 = "        double wz = R[2][0] * p[0] + R[2][1] * p[1] + R[2][2] * p[2] + z - tb_cam[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9986; }
