    { const char * tb_v10060 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10060; }
    { const char * tb_v10061 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v10061; }
