    { const char * tb_v10078 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10078; }
    { const char * tb_v10079 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10079; }
