    { const char * tb_v10086 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v10086; }
    { const char * tb_v10087 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v10087; }
    { const char * tb_v10088 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v10088; }
    { const char * tb_v10089 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10089; }
    { const char * tb_v10090 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v10090; }
