    { const char * tb_v10096 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10096; }
    { const char * tb_v10097 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v10097; }
    { const char * tb_v10098 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10098; }
    { const char * tb_v10099 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10099; }
    { const char * tb_v10100 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v10100; }
    { const char * tb_v10101 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v10101; }
    { const char * tb_v10102 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10102; }
    { const char * tb_v10103 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10103; }
    { const char * tb_v10104 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10104; }
    { const char * tb_v10105 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v10105; }
    { const char * tb_v10106 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10106; }
    { const char * tb_v10107 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10107; }
    { const char * tb_v10108 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v10108; }
    { const char * tb_v10109 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v10109; }
    { const char * tb_v10110 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10110; }
    { const char * tb_v10111 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10111; }
