    { const char * tb_v10406 = "        p->b[TB_PB_DOWN] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"down\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10406; }
    { const char * tb_v10407 = "        p->b[TB_PB_LEFT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"left\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10407; }
    { const char * tb_v10408 = "        p->b[TB_PB_RIGHT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"right\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10408; }
    { const char * tb_v10409 = "        id ls = TB_MSG(id, g, \"leftThumbstick\"), rs = TB_MSG(id, g, \"rightThumbstick\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10409; }
    { const char * tb_v10410 = "        p->a[TB_PA_LX] = TB_MSG(float, TB_MSG(id, ls, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10410; }
    { const char * tb_v10411 = "        p->a[TB_PA_LY] = -TB_MSG(float, TB_MSG(id, ls, \"yAxis\"), \"value\");   // у Apple вверх — плюс\n"; *(const char * *)tb_grow(v_lines) = tb_v10411; }
    { const char * tb_v10412 = "        p->a[TB_PA_RX] = TB_MSG(float, TB_MSG(id, rs, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10412; }
