    { const char * tb_v10420 = "typedef struct { unsigned long packet; tb_xpad pad; } tb_xstate;\n"; *(const char * *)tb_grow(v_lines) = tb_v10420; }
    { const char * tb_v10421 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10421; }
    { const char * tb_v10422 = "    static unsigned long (__stdcall *get)(unsigned long, tb_xstate *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10422; }
    { const char * tb_v10423 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10423; }
