    { const char * tb_v10425 = "        tried = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10425; }
    { const char * tb_v10426 = "        HMODULE h = LoadLibraryA(\"xinput1_4.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10426; }
    { const char * tb_v10427 = "        if (!h) h = LoadLibraryA(\"xinput9_1_0.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10427; }
    { const char * tb_v10428 = "        if (h) get = (unsigned long (__stdcall *)(unsigned long, tb_xstate *))GetProcAddress(h, \"XInputGetState\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10428; }
    { const char * tb_v10429 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10429; }
    { const char * tb_v10430 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10430; }
    { const char * tb_v10431 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10431; }
    { const char * tb_v10432 = "        tb_xstate st; memset(&st, 0, sizeof st);\n"; *(const char * *)tb_grow(v_lines) = tb_v10432; }
    { const char * tb_v10433 = "        p->on = get && get((unsigned long)i, &st) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10433; }
    { const char * tb_v10434 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v10434; }
    { const char * tb_v10435 = "        unsigned short w = st.pad.buttons;\n"; *(const char * *)tb_grow(v_lines) = tb_v10435; }
    { const char * tb_v10436 = "        static const unsigned short bit[TB_PB_N] = { 0x1000, 0x2000, 0x4000, 0x8000, 0x0100, 0x0200, 0, 0, 0x0040, 0x0080, 0x0010, 0x0020, 0, 0x0001, 0x0002, 0x0004, 0x0008 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10436; }
    { const char * tb_v10437 = "        for (int k = 0; k < TB_PB_N; k++) p->b[k] = bit[k] ? (w & bit[k]) != 0 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10437; }
    { const char * tb_v10438 = "        p->b[TB_PB_L2] = st.pad.lt > 30; p->b[TB_PB_R2] = st.pad.rt > 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v10438; }
    { const char * tb_v10439 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10439; }
    { const char * tb_v10440 = "        p->a[TB_PA_RX] = st.pad.rx / 32767.0; p->a[TB_PA_RY] = -st.pad.ry / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10440; }
    { const char * tb_v10441 = "        p->a[TB_PA_L2] = st.pad.lt / 255.0; p->a[TB_PA_R2] = st.pad.rt / 255.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10441; }
    { const char * tb_v10442 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10442; }
    { const char * tb_v10443 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10443; }
    { const char * tb_v10444 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v10444; }
    { const char * tb_v10445 = "#include <fcntl.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v10445; }
    { const char * tb_v10446 = "TB_API int tb_pad_fd[TB_PADS] = { -1, -1, -1, -1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10446; }
    { const char * tb_v10447 = "TB_API long long tb_pad_look = -100000;\n"; *(const char * *)tb_grow(v_lines) = tb_v10447; }
    { const char * tb_v10448 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10448; }
    { const char * tb_v10449 = "    // новые геймпады ищем раз в 2 секунды\n"; *(const char * *)tb_grow(v_lines) = tb_v10449; }
    { const char * tb_v10450 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v10450; }
    { const char * tb_v10451 = "    if (now - tb_pad_look > 2000) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10451; }
    { const char * tb_v10452 = "        tb_pad_look = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v10452; }
    { const char * tb_v10453 = "        for (int i = 0; i < TB_PADS; i++) if (tb_pad_fd[i] < 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10453; }
    { const char * tb_v10454 = "            char path[32]; snprintf(path, sizeof path, \"/dev/input/js%d\", i);\n"; *(const char * *)tb_grow(v_lines) = tb_v10454; }
    { const char * tb_v10455 = "            tb_pad_fd[i] = open(path, O_RDONLY | O_NONBLOCK);\n"; *(const char * *)tb_grow(v_lines) = tb_v10455; }
    { const char * tb_v10456 = "            if (tb_pad_fd[i] >= 0) memset(&tb_pads[i], 0, sizeof tb_pads[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10456; }
    { const char * tb_v10457 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10457; }
    { const char * tb_v10458 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10458; }
    { const char * tb_v10459 = "    // раскладка xpad (Xbox и большинство совместимых): кнопки 0 A, 1 B, 2 X, 3 Y, 4 LB, 5 RB, 6 back, 7 start, 8 home, 9 L3, 10 R3;\n"; *(const char * *)tb_grow(v_lines) = tb_v10459; }
    { const char * tb_v10460 = "    // оси 0 lx, 1 ly, 2 lt, 3 rx, 4 ry, 5 rt, 6 крестовина x, 7 крестовина y\n"; *(const char * *)tb_grow(v_lines) = tb_v10460; }
    { const char * tb_v10461 = "    static const int bmap[11] = { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_SELECT, TB_PB_START, TB_PB_HOME, TB_PB_L3, TB_PB_R3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10461; }
    { const char * tb_v10462 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10462; }
    { const char * tb_v10463 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10463; }
    { const char * tb_v10464 = "        p->on = tb_pad_fd[i] >= 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10464; }
    { const char * tb_v10465 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v10465; }
    { const char * tb_v10466 = "        struct { unsigned int time; short value; unsigned char type, number; } e;\n"; *(const char * *)tb_grow(v_lines) = tb_v10466; }
    { const char * tb_v10467 = "        long long got;\n"; *(const char * *)tb_grow(v_lines) = tb_v10467; }
    { const char * tb_v10468 = "        while ((got = read(tb_pad_fd[i], &e, sizeof e)) == (long long)sizeof e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10468; }
    { const char * tb_v10469 = "            int t = e.type & 0x7f;\n"; *(const char * *)tb_grow(v_lines) = tb_v10469; }
    { const char * tb_v10470 = "            if (t == 1 && e.number < 11) p->b[bmap[e.number]] = e.value != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10470; }
    { const char * tb_v10471 = "            else if (t == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10471; }
    { const char * tb_v10472 = "                double v = e.value / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10472; }
    { const char * tb_v10473 = "                if (v < -1) v = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10473; }
    { const char * tb_v10474 = "                switch (e.number) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10474; }
    { const char * tb_v10475 = "                case 0: p->a[TB_PA_LX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10475; }
    { const char * tb_v10476 = "                case 1: p->a[TB_PA_LY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10476; }
    { const char * tb_v10477 = "                case 2: p->a[TB_PA_L2] = (v + 1) / 2; p->b[TB_PB_L2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10477; }
    { const char * tb_v10478 = "                case 3: p->a[TB_PA_RX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10478; }
    { const char * tb_v10479 = "                case 4: p->a[TB_PA_RY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10479; }
    { const char * tb_v10480 = "                case 5: p->a[TB_PA_R2] = (v + 1) / 2; p->b[TB_PB_R2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10480; }
    { const char * tb_v10481 = "                case 6: p->b[TB_PB_LEFT] = e.value < -8000; p->b[TB_PB_RIGHT] = e.value > 8000; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10481; }
    { const char * tb_v10482 = "                case 7: p->b[TB_PB_UP] = e.value < -8000; p->b[TB_PB_DOWN] = e.value > 8000; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v10482; }
    { const char * tb_v10483 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v10483; }
    { const char * tb_v10484 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10484; }
    { const char * tb_v10485 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10485; }
    { const char * tb_v10486 = "        if (got < 0 && errno != EAGAIN && errno != EWOULDBLOCK) { close(tb_pad_fd[i]); tb_pad_fd[i] = -1; p->on = 0; }   // выдернули\n"; *(const char * *)tb_grow(v_lines) = tb_v10486; }
    { const char * tb_v10487 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10487; }
