    { const char * tb_v10493 = "    if (now - tb_pad_t < 4) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10493; }
    { const char * tb_v10494 = "    tb_pad_t = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v10494; }
    { const char * tb_v10495 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10495; }
    { const char * tb_v10496 = "    tb_pad_poll();\n"; *(const char * *)tb_grow(v_lines) = tb_v10496; }
    { const char * tb_v10497 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10497; }
    { const char * tb_v10498 = "TB_API long long tb_pad_count(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10498; }
    { const char * tb_v10499 = "    tb_pad_fresh();\n"; *(const char * *)tb_grow(v_lines) = tb_v10499; }
    { const char * tb_v10500 = "    long long n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10500; }
    { const char * tb_v10501 = "    for (int i = 0; i < TB_PADS; i++) if (tb_pads[i].on) n = i + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10501; }
