    { const char * tb_v10505 = "    static const char *names[TB_PB_N] = { \"a\", \"b\", \"x\", \"y\", \"l1\", \"r1\", \"l2\", \"r2\", \"l3\", \"r3\", \"start\", \"select\", \"home\", \"up\", \"down\", \"left\", \"right\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v10505; }
    { const char * tb_v10506 = "    tb_pad_fresh();\n"; *(const char * *)tb_grow(v_lines) = tb_v10506; }
