    { const char * tb_v10550 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v10550; }
    { const char * tb_v10551 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v10551; }
    { const char * tb_v10552 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v10552; }
    { const char * tb_v10553 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v10553; }
    { const char * tb_v10554 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v10554; }
    { const char * tb_v10555 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v10555; }
    { const char * tb_v10556 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v10556; }
    { const char * tb_v10557 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v10557; }
    { const char * tb_v10558 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v10558; }
    { const char * tb_v10559 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v10559; }
    { const char * tb_v10560 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v10560; }
    { const char * tb_v10561 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v10561; }
    { const char * tb_v10562 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v10562; }
    { const char * tb_v10563 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v10563; }
    { const char * tb_v10564 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v10564; }
    { const char * tb_v10565 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v10565; }
    { const char * tb_v10566 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v10566; }
    { const char * tb_v10567 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10567; }
    { const char * tb_v10568 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v10568; }
    { const char * tb_v10569 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v10569; }
    { const char * tb_v10570 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v10570; }
    { const char * tb_v10571 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v10571; }
    { const char * tb_v10572 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v10572; }
    { const char * tb_v10573 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v10573; }
    { const char * tb_v10574 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v10574; }
    { const char * tb_v10575 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10575; }
    { const char * tb_v10576 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v10576; }
    { const char * tb_v10577 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v10577; }
    { const char * tb_v10578 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v10578; }
    { const char * tb_v10579 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v10579; }
    { const char * tb_v10580 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v10580; }
    { const char * tb_v10581 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v10581; }
    { const char * tb_v10582 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v10582; }
    { const char * tb_v10583 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10583; }
    { const char * tb_v10584 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10584; }
    { const char * tb_v10585 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10585; }
    { const char * tb_v10586 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v10586; }
    { const char * tb_v10587 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v10587; }
    { const char * tb_v10588 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10588; }
    { const char * tb_v10589 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10589; }
    { const char * tb_v10590 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10590; }
    { const char * tb_v10591 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10591; }
    { const char * tb_v10592 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10592; }
    { const char * tb_v10593 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10593; }
    { const char * tb_v10594 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v10594; }
    { const char * tb_v10595 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10595; }
    { const char * tb_v10596 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v10596; }
    { const char * tb_v10597 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10597; }
    { const char * tb_v10598 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v10598; }
    { const char * tb_v10599 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v10599; }
    { const char * tb_v10600 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v10600; }
    { const char * tb_v10601 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10601; }
    { const char * tb_v10602 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v10602; }
    { const char * tb_v10603 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v10603; }
    { const char * tb_v10604 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10604; }
    { const char * tb_v10605 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10605; }
    { const char * tb_v10606 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v10606; }
    { const char * tb_v10607 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10607; }
    { const char * tb_v10608 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10608; }
    { const char * tb_v10609 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v10609; }
    { const char * tb_v10610 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10610; }
    { const char * tb_v10611 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10611; }
    { const char * tb_v10612 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v10612; }
    { const char * tb_v10613 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10613; }
    { const char * tb_v10614 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10614; }
    { const char * tb_v10615 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v10615; }
    { const char * tb_v10616 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10616; }
    { const char * tb_v10617 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10617; }
    { const char * tb_v10618 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v10618; }
    { const char * tb_v10619 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10619; }
    { const char * tb_v10620 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10620; }
    { const char * tb_v10621 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10621; }
    { const char * tb_v10622 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10622; }
    { const char * tb_v10623 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10623; }
    { const char * tb_v10624 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v10624; }
    { const char * tb_v10625 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v10625; }
    { const char * tb_v10626 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v10626; }
    { const char * tb_v10627 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v10627; }
    { const char * tb_v10628 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v10628; }
    { const char * tb_v10629 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v10629; }
    { const char * tb_v10630 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10630; }
    { const char * tb_v10631 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10631; }
    { const char * tb_v10632 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v10632; }
    { const char * tb_v10633 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v10633; }
    { const char * tb_v10634 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v10634; }
    { const char * tb_v10635 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v10635; }
    { const char * tb_v10636 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v10636; }
    { const char * tb_v10637 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v10637; }
    { const char * tb_v10638 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v10638; }
    { const char * tb_v10639 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10639; }
    { const char * tb_v10640 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10640; }
    { const char * tb_v10641 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v10641; }
    { const char * tb_v10642 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v10642; }
    { const char * tb_v10643 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v10643; }
    { const char * tb_v10644 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10644; }
    { const char * tb_v10645 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10645; }
    { const char * tb_v10646 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10646; }
    { const char * tb_v10647 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10647; }
    { const char * tb_v10648 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10648; }
